function applyPermissions(){
  if(!canManageProject){
    $$('[data-new-project],[data-seed],[data-save] input,[data-save] textarea,[data-save] select,[data-save] button,[data-add] input,[data-add] select,[data-add] button,[data-add-planning],[data-move-wbs],[data-remove],[data-submit-charter],[data-approve-charter],[data-request-charter],[data-revise-charter],[data-submit-business],[data-approve-business],[data-request-business],[data-revise-business],[data-baseline],[data-approve-scope],[data-revise-scope],[data-approve-change],[data-create-controlled] input,[data-create-controlled] textarea,[data-create-controlled] select,[data-create-controlled] button,[data-transition-document],[data-revise-document]').forEach(element=>element.disabled=true);
    const workspace=$('[data-workspace]');
    if(active()&&workspace&&!workspace.querySelector('[data-read-only-note]'))workspace.insertAdjacentHTML('afterbegin',`<p class="permission-note" data-read-only-note>Read-only project access · role: ${esc(cloud.role.replace('_',' '))}</p>`);
  }
  if(!canUploadDocument)$$('[data-document-upload] input,[data-document-upload] button').forEach(element=>element.disabled=true);
}
function businessFromForm(form,current){const values={...current},keys=['executiveSummary','background','problemOpportunity','strategicAlignment','expectedOutcomes','fundingAssumptions','keyRisks','dependencies','constraints','sustainabilityImpact','recommendedOption','recommendationRationale','estimatedCost','estimatedBenefit','discountRate','cashFlows'];for(const key of keys)if(form.elements[key])values[key]=form.elements[key].value;values.options=$$('[data-option-index]',form).map((fieldset,index)=>({id:current.options?.[index]?.id||uid(),title:$('[name="title"]',fieldset).value.trim(),description:$('[name="description"]',fieldset).value.trim(),benefits:$('[name="benefits"]',fieldset).value.trim(),drawbacks:$('[name="drawbacks"]',fieldset).value.trim(),riskSummary:$('[name="riskSummary"]',fieldset).value.trim(),estimatedCost:num($('[name="estimatedCost"]',fieldset).value),durationMonths:num($('[name="durationMonths"]',fieldset).value),scores:{strategicFit:num($('[name="strategicFit"]',fieldset).value),benefit:num($('[name="benefit"]',fieldset).value),affordability:num($('[name="affordability"]',fieldset).value),deliverability:num($('[name="deliverability"]',fieldset).value),risk:num($('[name="risk"]',fieldset).value)},sortOrder:index}));return values}
function planningFromForm(form,current){if(!form)return current;const values={...current},topKeys=['planSummary','governanceApproach','lifecycleModel','thresholds','escalationRules','tailoringDecisions','productScope','projectScope','deliverables','acceptanceCriteria','inclusions','exclusions','assumptions','constraints','boundaries','interfaces'];for(const key of topKeys){const input=$(`[name="${key}"]`,form);if(input)values[key]=input.value}values.subsidiaryPlans=$$('[data-plan-index]',form).map(group=>{const plan={type:group.dataset.planType};for(const [key] of [['status'],...planFields])plan[key]=$(`[name="${key}"]`,group)?.value||'';return plan});values.requirements=$$('[data-requirement-index]',form).map((group,index)=>{const prior=current.requirements?.[index]||{};return{...prior,...Object.fromEntries(['code','description','category','source','owner','stakeholder','priority','status','acceptanceCriteria','rationale','targetRelease','verificationMethod','validationMethod','objective','benefit','deliverable','wbs','activity','evidence','changeHistory'].map(key=>[key,$(`[name="${key}"]`,group)?.value||''])),traceStatus:($('[name="deliverable"]',group)?.value&&$('[name="wbs"]',group)?.value)?'Traced':'Untraced'}});values.wbs=$$('[data-wbs-index]',form).map((group,index)=>{const prior=current.wbs?.[index]||{},dictionary=Object.fromEntries(['description','scope','acceptanceCriteria','milestonesDependencies','assumptionsConstraints','qualityReferences'].map(key=>[key,$(`[name="${key}"]`,group)?.value||'']));return{...prior,key:prior.key||uid(),sortOrder:index,...Object.fromEntries(['outline','name','parentKey','owner','type','effort','cost','requirements','deliverables'].map(key=>[key,$(`[name="${key}"]`,group)?.value||''])),dictionary}});return values}
async function refreshInitiation(project,result){const initiation=await loadProjectInitiation(project.id);if(initiation.business)project.business={...project.business,...initiation.business};if(initiation.charter)project.charter={...project.charter,...initiation.charter};if(result?.projectVersion)project._version=result.projectVersion;render()}
async function refreshPlanning(project){const planning=await loadProjectPlanning(project.id);if(Object.keys(planning).length)project.planning={...project.planning,...planning};render()}
async function savePlanningDraft(form=$('[data-save="planning"]'),announce=true){const project=active();project.planning=planningFromForm(form,project.planning);try{await saveCorePlanning(project.id,project.planning);await refreshPlanning(project);if(announce)notify('Planning saved','The master plan, scope, requirements, RTM, WBS and dictionary were saved atomically.');return true}catch(error){notify('Planning not saved',error.message);return false}}
async function saveBusinessDraft(form=$('[data-save="business"]'),announce=true){const project=active();project.business=businessFromForm(form,project.business);try{await saveBusinessCase(project.id,project.business);await refreshInitiation(project);if(announce)notify('Business case saved','The governed draft and its options were saved securely.');return true}catch(error){notify('Business case not saved',error.message);return false}}
async function saveCharterDraft(form=$('[data-save="charter"]'),announce=true){const project=active(),values=Object.fromEntries(new FormData(form));Object.assign(project.charter,values);try{await saveProjectCharter(project.id,project.charter);await refreshInitiation(project);if(announce)notify('Charter saved','The governed charter draft was saved securely.');return true}catch(error){notify('Charter not saved',error.message);return false}}
async function initiationAction(section,nextStatus){const project=active(),artifact=project[section],form=$(`[data-save="${section}"]`);if(nextStatus==='in_review'){const saved=section==='business'?await saveBusinessDraft(form,false):await saveCharterDraft(form,false);if(!saved)return}let comments='';if(nextStatus==='changes_requested'){comments=prompt('Required change-request comments:','')?.trim()||'';if(!comments){notify('Comments required','Explain the changes required before returning this version.');return}}try{const result=section==='business'?await transitionBusinessCase(project.id,project.business.version,nextStatus,comments):await transitionProjectCharter(project.id,project.charter.version,nextStatus,comments);if(section==='charter'&&nextStatus==='approved')project.status='Authorized';await refreshInitiation(project,result);notify('Decision recorded',`${section==='business'?'Business case':'Project charter'} is now ${nextStatus.replaceAll('_',' ')}.`)}catch(error){notify('Decision not recorded',error.message)}}
async function setView(view){const workspaceViews=['communications','integrations','team'];if(workspaceViews.includes(view)&&!cloud.workspace){notify('Create a workspace','Create your secure workspace before opening shared tools.');return}if(!active()&&view!=='overview'&&!workspaceViews.includes(view)){notify('Select a project','Open or create a project before using this control area.');return}state.view=view;save();$('#rail').classList.remove('open');if(['communications','integrations'].includes(view)){render();try{await loadStudio(cloud)}catch(error){notify('Workspace tools unavailable',error.message)}}if(view==='team'){render();try{await loadTeam(cloud)}catch(error){notify('Team unavailable',error.message)}}if(view==='documents'&&(active()._documents===null||active()._controlledDocuments===null)){render();try{const [files,documents]=await Promise.all([active()._documents===null?listDocuments(active().id):active()._documents,active()._controlledDocuments===null?listControlledDocuments(active().id):active()._controlledDocuments]);active()._documents=files;active()._controlledDocuments=documents}catch(error){notify('Documents unavailable',error.message)}}render()}
function goHome(){state.activeId=null;state.view='overview';save();render()}
function exportProject(format){const project=active();let content='',type='text/plain',extension=format;if(format==='json'){content=JSON.stringify({schemaVersion:'arkhimar-pm-project-v1',exportedAt:new Date().toISOString(),project},null,2);type='application/json'}else if(format==='csv'){const rows=[['register','id','title','owner','status'],...project.controls.risks.map(x=>['risk',x.id,x.title,x.owner,x.status]),...project.controls.issues.map(x=>['issue',x.id,x.title,x.owner,x.status]),...project.controls.changes.map(x=>['change',x.id,x.title,x.owner,x.status]),...project.planning.requirements.map(x=>['requirement',x.code||x.id,x.description,x.owner,x.priority])];content=rows.map(row=>row.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n');type='text/csv'}else if(format==='txt'){content=`ARKHIMAR PM PROJECT PACK\n${project.title} (${project.code})\nGenerated: ${new Date().toISOString()}\nClassification: ${project.confidentiality}\n\nBUSINESS NEED\n${project.problem}\n\nEXPECTED OUTCOME\n${project.outcome}\n\nCHARTER (${project.charter.status} v${project.charter.version})\n${project.charter.purpose}\n\nSCOPE\n${project.planning.projectScope}\n\nSTATUS\nReadiness: ${completion(project)}%\nRisks: ${project.controls.risks.length}\nIssues: ${project.controls.issues.length}\n` }else{audit(project,'Exported','project report','Opened print/PDF view');save();window.print();return}const blob=new Blob([content],{type:`${type};charset=utf-8`}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`ARKHIMAR_PM_${project.code}_${today()}.${extension}`;link.click();URL.revokeObjectURL(link.href);audit(project,'Exported','project data',format.toUpperCase());save();render()}

function seedDemo(){const p=projectModel({title:'Lagos Civic Learning Hub',code:'AKH-026',description:'A climate-responsive civic learning and community facility.',industry:'Architecture / Construction',approach:'Hybrid',problem:'Limited access to flexible, digitally enabled community learning space.',outcome:'Deliver an inclusive learning hub with measurable community use and energy performance.',objectives:'Expand learning access; demonstrate climate-responsive public architecture',successCriteria:'Practical completion by Q4; 20% energy improvement; client acceptance',benefits:'Higher learning capacity and civic participation',start:'2026-09-14',finish:'2027-06-30',sponsor:'Lagos Civic Foundation',projectManager:'A. Himar',governance:'Standard stage gates',template:'Construction / Architecture'});p.business={...p.business,executiveSummary:'Develop a flexible civic learning hub that combines classrooms, digital access and public gathering space.',recommendedOption:'Phased design-and-build delivery',estimatedCost:480000000,estimatedBenefit:650000000,discountRate:10,cashFlows:'-480000000, 90000000, 130000000, 180000000, 250000000'};p.charter={...p.charter,purpose:p.business.executiveSummary,scope:'Design, approvals, construction, fit-out and operational handover.',deliverables:'Approved design; constructed facility; digital learning fit-out; handover package',milestones:'Design approval; planning approval; structure complete; practical completion',budget:'NGN 480,000,000',risks:'Planning approval delay; material inflation; rainy-season disruption',authority:'Manage approved resources and escalate forecast variances over 10%.',status:'Approved',approvedSnapshot:{version:1},version:1};p.planning.projectScope=p.charter.scope;p.planning.acceptanceCriteria='Regulatory approval, snag closure and signed client acceptance.';p.planning.requirements=[{id:uid(),code:'REQ-001',description:'Accessible learning spaces for 200 concurrent users',owner:'Design Lead',priority:'Must',status:'Proposed',traceStatus:'Untraced'},{id:uid(),code:'REQ-002',description:'20% operational energy improvement against baseline',owner:'Sustainability Lead',priority:'Should',status:'Proposed',traceStatus:'Untraced'}];p.planning.wbs=[{id:uid(),key:uid(),outline:'1',sortOrder:0,type:'Control account',name:'Design and approvals',owner:'Design Lead',dictionary:{}},{id:uid(),key:uid(),outline:'2',sortOrder:1,type:'Work package',name:'Construction',owner:'Site Lead',dictionary:{}},{id:uid(),key:uid(),outline:'3',sortOrder:2,type:'Work package',name:'Fit-out and handover',owner:'Project Manager',dictionary:{}}];const t1=uid(),t2=uid(),t3=uid(),t4=uid();p.schedule.tasks=[{id:t1,name:'Concept and stakeholder validation',duration:15,predecessor:''},{id:t2,name:'Detailed design and approvals',duration:35,predecessor:t1},{id:t3,name:'Construction and fit-out',duration:140,predecessor:t2},{id:t4,name:'Commissioning and handover',duration:12,predecessor:t3}];p.cost={...p.cost,bac:480000000,pv:120000000,ev:108000000,ac:105000000,contingency:30000000,reserve:20000000};p.controls.risks=[{id:uid(),title:'Planning approval delay affects mobilisation',owner:'Project Manager',probability:3,impact:4,status:'Monitoring'},{id:uid(),title:'Material price escalation exceeds allowance',owner:'Cost Consultant',probability:4,impact:4,status:'Open'}];p.controls.stakeholders=[{id:uid(),name:'Lagos Civic Foundation',role:'Sponsor',owner:'Project Manager',status:'Leading'}];audit(p,'Created','project','Loaded demonstration project');audit(p,'Approved','project charter','Charter version 1');createProject(cloud.workspace.id,p,cloud.session.user.id).then(stored=>Object.assign(p,stored)).catch(error=>notify('Project creation failed',error.message));state.projects.unshift(p);state.activeId=p.id;state.view='overview';save();render()}

const dialog=$('[data-project-dialog]'),projectForm=$('[data-project-form]'),steps=$$('[data-step]');let step=1;
function reviewProject(){const data=Object.fromEntries(new FormData(projectForm));$('[data-project-review]').innerHTML=`<dl><div><dt>Project</dt><dd>${esc(data.title)} (${esc(data.code)})</dd></div><div><dt>Approach</dt><dd>${esc(data.approach)} · ${esc(data.template)}</dd></div><div><dt>Outcome</dt><dd>${esc(data.outcome)}</dd></div><div><dt>Governance</dt><dd>${esc(data.governance)} · ${esc(data.reporting)} reporting</dd></div><div><dt>Accountability</dt><dd>${esc(data.sponsor)||'Sponsor unassigned'} · ${esc(data.projectManager)||'PM unassigned'}</dd></div></dl>`}
function showStep(next){step=next;steps.forEach(el=>el.classList.toggle('active',num(el.dataset.step)===step));$('[data-step-label]').textContent=`${step} OF ${steps.length}`;$('[data-track]').style.width=`${step/steps.length*100}%`;$('[data-back]').disabled=step===1;$('[data-next]').innerHTML=step===steps.length?'Create project <span>＋</span>':'Continue →';$('[data-wizard-status]').textContent='';if(step===6)reviewProject()}
function openProject(){if(!canManageProject){notify('Permission required','Only workspace owners, admins and project managers can create projects.');return}dialog.showModal();showStep(1);syncOtherIndustry();setTimeout(()=>projectForm.elements.title.focus(),50)}
function syncOtherIndustry(){const isOther=projectForm.elements.industry.value==='Other',label=$('[data-other-industry]');label.hidden=!isOther;if(!isOther)projectForm.elements.industryOther.value=''}
$('[data-industry]').addEventListener('change',syncOtherIndustry);
$('[data-back]').addEventListener('click',()=>showStep(Math.max(1,step-1)));$('[data-next]').addEventListener('click',async()=>{const current=steps[step-1],invalid=$$('input,select,textarea',current).find(input=>!input.checkValidity());if(invalid){invalid.reportValidity();$('[data-wizard-status]').textContent='Complete the required fields.';return}if(step<steps.length){showStep(step+1);return}const data=Object.fromEntries(new FormData(projectForm));if(data.start&&data.finish&&data.finish<data.start){$('[data-wizard-status]').textContent='Finish date must be after the start date.';return}if(data.industry==='Other'&&data.industryOther.trim())data.industry=data.industryOther.trim();delete data.industryOther;let project=projectModel(data);audit(project,'Created','project',`Created from ${project.template} template`);const button=$('[data-next]');button.disabled=true;try{project=await createProject(cloud.workspace.id,project,cloud.session.user.id)}catch(error){notify('Project creation failed',error.message);button.disabled=false;return}state.projects.unshift(project);state.activeId=project.id;state.view='overview';save();projectForm.reset();dialog.close();button.disabled=false;render()});
const rail=$('#rail');$('[data-collapse]').addEventListener('click',()=>rail.classList.toggle('collapsed'));$('[data-mobile]').addEventListener('click',event=>{const open=rail.classList.toggle('open');event.currentTarget.setAttribute('aria-expanded',String(open))});$$('[data-view]').forEach(button=>button.addEventListener('click',()=>setView(button.dataset.view)));$('[data-home]').addEventListener('click',goHome);
const commandDialog=$('[data-command-dialog]'),commandInput=$('[data-command-input]');function commandResults(query=''){const choices=[{label:'Create a project',action:'new'},...state.projects.map(p=>({label:`Open ${p.title}`,id:p.id})),{label:'Return to all projects',action:'home'}].filter(x=>x.label.toLowerCase().includes(query.toLowerCase()));$('[data-command-results]').innerHTML=choices.map((x,i)=>`<li><button type="button" data-command-choice="${x.action||x.id}">${esc(x.label)}${i===0?' <kbd>Enter</kbd>':''}</button></li>`).join('')||'<li><p>No matching project or command.</p></li>';$$('[data-command-choice]').forEach(b=>b.addEventListener('click',()=>{commandDialog.close();if(b.dataset.commandChoice==='new')openProject();else if(b.dataset.commandChoice==='home')goHome();else{state.activeId=b.dataset.commandChoice;state.view='overview';save();render()}}))}function openCommand(){commandResults();commandDialog.showModal();setTimeout(()=>commandInput.focus(),20)}$('[data-command]').addEventListener('click',openCommand);commandInput.addEventListener('input',()=>commandResults(commandInput.value));
$('[data-notifications]').addEventListener('click',()=>notify('Notifications','No new workspace notifications.'));initializeAccount(cloud);
addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openCommand()}if(event.key==='Escape')rail.classList.remove('open')});
render();
if(state.view==='documents'&&active()&&(active()._documents===null||active()._controlledDocuments===null))setView('documents');
